using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEditor;using CatGunner.Runtime;
public static class ModeUiV3Preview {
 const string Dir="/Volumes/ZHITAI_1T/IdleCatGunner/art/reskin/penguin-expedition/mode-ui-v3";
 static GameClient Client(){if(Application.dataPath!="/Volumes/ZHITAI_1T/IdleCatGunner/reconstruction/CatGunnerUnityClient/Assets")throw new Exception("Wrong project");return UnityEngine.Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);}
 public static object Prepare(){var c=Client();if(Application.isPlaying)throw new Exception("EditMode required");var state=new{c.Persist,c.SaveFolderOverride,host=SessionState.GetString("CatGunner.Recovery.TestHostFolder","")};File.WriteAllText(Dir+"/preview-state.json",Newtonsoft.Json.JsonConvert.SerializeObject(state));SessionState.SetString("CatGunner.Recovery.TestHostFolder",Path.Combine(Application.temporaryCachePath,"ModeUiPreview-"+Guid.NewGuid().ToString("N")));c.Persist=false;return state;}
 public static object Restore(){var c=Client();if(Application.isPlaying)throw new Exception("EditMode required");var s=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(Dir+"/preview-state.json"));c.Persist=(bool)s["Persist"];c.SaveFolderOverride=s["SaveFolderOverride"].Type==Newtonsoft.Json.Linq.JTokenType.Null?null:(string)s["SaveFolderOverride"];SessionState.SetString("CatGunner.Recovery.TestHostFolder",(string)s["host"]);return new{c.Persist,c.SaveFolderOverride};}
 public static string Capture(string batch="before"){var c=Client();if(!Application.isPlaying||!c.SaveFolderOverride.Contains("ModeUiPreview"))throw new Exception("Isolated preview required");if(File.Exists(Dir+"/"+batch+"/complete.json"))File.Delete(Dir+"/"+batch+"/complete.json");c.StartCoroutine(Run(c,batch));return "Capturing "+batch;}
 public static string Ability(string batch){var c=Client();if(!Application.isPlaying||!c.SaveFolderOverride.Contains("ModeUiPreview"))throw new Exception("Isolated preview required");c.StartCoroutine(AbilityRun(c,batch));return "Capturing ability tab";}
 static IEnumerator AbilityRun(GameClient c,string batch){while(!c.ReadyForPlay||!c.GetComponent<PenguinPlaytestPolish>().Ready)yield return null;c.DailyLogin.AutoShow=false;c.DailyLogin.Close();c.Tutorial.SetCleared();c.Offline.offlinePanelUI.gameObject.SetActive(false);c.GetComponent<Language>().PersistSelection=false;c.GetComponent<Language>().Select("zh-CN");ForestRuntimeAcceptance.IsGaming=false;var a=c.Adventure;a.Open();yield return new WaitForSecondsRealtime(.5f);yield return Shot(Dir+"/"+batch,"Adventure");var b=a.LocalTabs.Btn_list[1].GetComponent<Button>();yield return Click(b);yield return Shot(Dir+"/"+batch,"Adventure-ability");var before=(int[])c.State.Adventure_Currency_Core.Clone();c.State.Adventure_Currency_Core[0]=100;Relic_manager.instance.UI_Reload();yield return Shot(Dir+"/"+batch,"Adventure-ability-enabled");var draws=Relic_manager.instance.relic_DownPanel.Draw_Relic_Btn_list.Select(d=>new{d.DrawCount,price=d.Price_txt.color.ToString(),labels=d.ActionLabels.Select(t=>t.color.ToString()).ToArray(),panel=d.Panel_img.color.ToString()}).ToArray();c.State.Adventure_Currency_Core=before;Relic_manager.instance.UI_Reload();a.Close();File.WriteAllText(Dir+"/"+batch+"/ability-complete.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{clickedNativeTab=true,draws}));}
 static IEnumerator Shot(string folder,string name){yield return new WaitForSecondsRealtime(.6f);yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(folder+"/"+name+".png",t.EncodeToPNG());}finally{UnityEngine.Object.Destroy(t);}}
 static IEnumerator Click(Button b){var module=EventSystem.current.GetComponent<StandaloneInputModule>();var mouse=module.gameObject.AddComponent<ForestFeedbackMouseFixture>();module.inputOverride=mouse;Canvas.ForceUpdateCanvases();var r=(RectTransform)b.transform;mouse.Position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center));yield return null;mouse.Down=mouse.Held=true;yield return null;mouse.Down=mouse.Held=false;mouse.Up=true;yield return null;mouse.Up=false;yield return null;module.inputOverride=null;UnityEngine.Object.Destroy(mouse);}
 static IEnumerator Catalogue(GameClient c,string folder){var p=c.GetComponent<ClientPresentation>();var canvas=c.Slider.GetComponentInParent<Canvas>();var root=canvas.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Gun_UI  (SafeArea)");var button=root.Find("GunList_UI/Panel/Menu (Gun List)/Collection_Btn").GetComponent<Button>();int dia=c.State.Dia;var owned=(int[])c.State.Owned_Gun_list.Clone();var selected=(int[])c.State.Selected_items.Clone();var collected=(bool[])c.State.Gun_Collect.Clone();CheckHit(button);yield return Click(button);yield return Shot(folder,"Gun-collection");if(!p.Collection.gameObject.activeInHierarchy||p.Collection.Gun_Item_list.Length!=65)throw new Exception("Catalogue did not open");var item=p.Collection.Gun_Item_list[0].GetComponent<Button>();CheckHit(item);yield return Click(item);yield return Shot(folder,"Gun-detail");if(!c.Guns.gun_info_ui.gameObject.activeInHierarchy)throw new Exception("Detail did not open");var close=c.Guns.gun_info_ui.GetComponentsInChildren<Button>(true).Single(b=>b.name=="Close_Btn");CheckHit(close);yield return Click(close);if(c.Guns.gun_info_ui.gameObject.activeSelf)throw new Exception("Detail did not close");close=p.Collection.GetComponentsInChildren<Button>(true).Single(b=>b.name=="Close_Btn");CheckHit(close);yield return Click(close);if(p.Collection.gameObject.activeSelf)throw new Exception("Catalogue did not close");if(c.State.Dia!=dia||!owned.SequenceEqual(c.State.Owned_Gun_list)||!selected.SequenceEqual(c.State.Selected_items)||!collected.SequenceEqual(c.State.Gun_Collect))throw new Exception("Catalogue changed player state");File.WriteAllText(folder+"/catalogue-check.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=true,interactable=button.interactable,items=65,opened=true,detailOpened=true,closed=true,inventoryUnchanged=true,source="StandaloneInputModule actual pointer clicks with raycast hit checks"}));}
 static void CheckHit(Button b){Canvas.ForceUpdateCanvases();if(!b.gameObject.activeInHierarchy||!b.IsInteractable())throw new Exception("Unavailable button: "+AnimationUtility.CalculateTransformPath(b.transform,null)+" active="+b.gameObject.activeInHierarchy+" interactable="+b.IsInteractable());var r=(RectTransform)b.transform;var pos=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center));var hits=new System.Collections.Generic.List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=pos},hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<Button>()!=b)throw new Exception("Blocked button "+b.name+": "+string.Join("|",hits.Take(4).Select(h=>h.gameObject.name)));}
 static IEnumerator Run(GameClient c,string batch){while(!c.ReadyForPlay||!c.GetComponent<PenguinPlaytestPolish>().Ready)yield return null;string folder=Dir+"/"+batch;Directory.CreateDirectory(folder);c.DailyLogin.AutoShow=false;c.DailyLogin.Close();c.Tutorial.SetCleared();c.Offline.offlinePanelUI.gameObject.SetActive(false);c.MissionUI.Panel_Close();c.Forest.Stage_Value_Max=400;c.State.Stage_Value_Max=400;c.OfflinePurchaseSimulation=true;c.ContentUnlock.Reload();c.GetComponent<Language>().PersistSelection=false;c.GetComponent<Language>().Select("zh-CN");c.State.PetCoin=250;c.State.Dia=10000;c.ApplyBalance();ForestRuntimeAcceptance.IsGaming=false;if(batch.StartsWith("after")){c.State.Selected_items[0]=15;c.State.Owned_Gun_list[0]=15;c.State.Pet_Selected_items[0]=3;c.State.Owned_Pet_list[0]=3;c.Guns.ReloadGunUI();c.PetUI.Pet_Reload();}
 var geometry=new System.Collections.Generic.List<object>();var canvas=c.Slider.GetComponentInParent<Canvas>();var menu=UiAuthoring.Find(canvas.transform,"SafeArea/Main_UI/Btn_list");
 yield return Shot(folder,"main");
 foreach(var key in batch=="palette-preview"?new[]{"Monster_Btn","Mine_Btn"}:new[]{"SpeedRun_Btn","Mine_Btn","Boss_Btn","Monster_Btn","Raid_Btn","Adventure_Btn","Pet_Btn ","Gun_Btn"}){
 var states=canvas.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t.gameObject,t=>t.gameObject.activeSelf);var b=menu.GetComponentsInChildren<Button>(true).FirstOrDefault(t=>t.name==key);
 if(b==null){File.AppendAllText(folder+"/missing.txt",key+"\n");continue;}yield return Click(b);
 
 yield return Shot(folder,key.Trim().Replace("_Btn",""));
 var visible=c.gameObject.scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<PenguinModeViewport>(true)).Where(v=>v.gameObject.activeInHierarchy).ToArray();
 foreach(var v in visible){var bounds=v.GetComponentsInChildren<Image>(false).Where(i=>i.name=="NonPurchase_Panel"||i.name=="Active_Panel"||i.name=="Panel"&&i.transform.parent==v.transform).Select(i=>{var corners=new Vector3[4];i.rectTransform.GetWorldCorners(corners);var points=corners.Select(x=>RectTransformUtility.WorldToScreenPoint(null,x)).ToArray();return new{path=v.name+"/"+i.name,minX=points.Min(x=>x.x),maxX=points.Max(x=>x.x),minY=points.Min(x=>x.y),maxY=points.Max(x=>x.y),alpha=i.color.a,opaque=i.color.a==1,sprite=i.sprite!=null?i.sprite.name:null,inViewport=points.All(x=>x.x>=-1&&x.x<=Screen.width+1&&x.y>=-1&&x.y<=Screen.height+1)};}).ToArray();geometry.Add(new{mode=v.name,bounds});}

 if(key=="Mine_Btn"){c.State.Is_Mine_Pack=true;c.MineMode.mineStart_ui.Reload();yield return Shot(folder,"Mine-plus-pack");c.State.Is_Mine_Pack=false;}
 if(key=="Pet_Btn "&&batch.StartsWith("after")){int before=c.State.PetCoin;var draw=c.PetUI.Pet_UI_obj.GetComponentsInChildren<Button>(true).Single(t=>t.name=="Draw_Btn");c.PetUI.Pet_Reload();yield return Click(draw);yield return Shot(folder,"Pet-draw");File.WriteAllText(folder+"/pet-draw.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{before,after=c.State.PetCoin,consumed=before-c.State.PetCoin,success=before-c.State.PetCoin==100,glyph=draw.transform.Find("Price_txt").GetComponent<TMPro.TMP_Text>().spriteAsset.name}));c.PetUI.newPet_ui.gameObject.SetActive(false);}

 if(key=="Gun_Btn"&&batch.StartsWith("after")){yield return Catalogue(c,folder);}
 foreach(var pair in states)if(pair.Key!=null&&pair.Key.activeSelf!=pair.Value)pair.Key.SetActive(pair.Value);
 }
 File.WriteAllText(folder+"/geometry.json",Newtonsoft.Json.JsonConvert.SerializeObject(geometry,Newtonsoft.Json.Formatting.Indented));
 File.WriteAllText(folder+"/complete.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{width=Screen.width,height=Screen.height,c.SaveFolderOverride,c.Persist,frames=Directory.GetFiles(folder,"*.png").Length,source="Unity Editor GPU frames; menu clicks through StandaloneInputModule"}));}
}
